function getDomainSet(targetDomain){
  const domainArr = targetDomain.split(".");
  let domain = `${domainArr[domainArr.length-2]}.${domainArr[domainArr.length-1]}`
  let domainSet = new Set([domain]);
  for (let i = domainArr.length-3; i >= 0; i--){
    domain = `${domainArr[i]}.${domain}`;
    domainSet.add(domain);
  }
  return domainSet;
}

